import numpy as np

def make_state(agent, rewards=(), movers=(), obstacles=(), prev=()):
    x = np.zeros((10,10,5), dtype=np.float32)
    x[0,:,3] = 1; x[9,:,3] = 1; x[:,0,3] = 1; x[:,9,3] = 1
    for r,c in obstacles:
        x[r,c,3] = 1
    x[agent[0], agent[1], 0] = 1
    for r,c in rewards:
        x[r,c,2] = 1
    for r,c in movers:
        x[r,c,1] = 1
    for r,c in prev:
        x[r,c,4] = 1
    return x.flatten()

agent = (5,5)
dirs = [(-1,0,'up'), (1,0,'down'), (0,-1,'left'), (0,1,'right'),
        (-1,-1,'up-left'), (-1,1,'up-right'), (1,-1,'down-left'), (1,1,'down-right')]

cases = []
labels = []

def add(label, **kwargs):
    cases.append(make_state(agent, **kwargs))
    labels.append(label)

add('baseline_prev_agent', prev=[agent])
add('baseline_prev_empty', prev=[])

for dr,dc,name in dirs:
    for d in [1,2]:
        r,c = agent[0]+dr*d, agent[1]+dc*d
        if 1 <= r <= 8 and 1 <= c <= 8:
            add(f'reward_{name}_d{d}', rewards=[(r,c)], prev=[agent])

for dr,dc,name in dirs:
    for d in [1,2]:
        r,c = agent[0]+dr*d, agent[1]+dc*d
        if 1 <= r <= 8 and 1 <= c <= 8:
            add(f'mover_{name}_d{d}', movers=[(r,c)], prev=[agent])

for dr,dc,name in dirs:
    r,c = agent[0]+dr, agent[1]+dc
    if 1 <= r <= 8 and 1 <= c <= 8:
        add(f'obstacle_{name}_d1', obstacles=[(r,c)], prev=[agent])

for dr,dc,name in dirs:
    r,c = agent[0]+dr, agent[1]+dc
    if 1 <= r <= 8 and 1 <= c <= 8:
        add(f'prev_{name}', prev=[(r,c)])

for dr,dc,name in dirs:
    r,c = agent[0]+dr, agent[1]+dc
    if 1 <= r <= 8 and 1 <= c <= 8:
        add(f'prev_mover_{name}', movers=[(r,c)], prev=[(r,c)])

add('conflict_reward_right_mover_left', rewards=[(5,7)], movers=[(5,3)], prev=[agent])
add('conflict_reward_left_mover_right', rewards=[(5,3)], movers=[(5,7)], prev=[agent])

X = np.stack(cases, axis=0)
logits = forward(X)
probs = np.exp(logits - logits.max(axis=1, keepdims=True))
probs = probs / probs.sum(axis=1, keepdims=True)
actions = ['noop','up','down','left','right']

